KG42.register("clusters-3adeea14344e1f68da088af1",{"id":"14-stackelberg_pv_sharing::v142-d-CL005","paper":"14-stackelberg_pv_sharing","label":"Restrictions on seller-player eligibility in the Cournot benchmark","record":{"cluster_id":"v142-d-CL005","label":"Restrictions on seller-player eligibility in the Cournot benchmark","market_meaning":"In the Cournot microgrid benchmark, only prosumers in the seller role can serve as game players.","mechanism_ids":["v141-a-M03"],"market_types":["LEM"],"process_stages":["participation"],"scope_disposition":"compatible","scope_explanation":"Both chains express the seller-player restriction of M03. This restriction targets game-player identity; it does not mean that buyers are prohibited from purchasing electricity, nor does it add geographical admission, device connection, or general prosumer participation restrictions.","assembly_status":"assembled","boundary_rationale":"Player eligibility has independent conditions and admission results and is retained as an independent Rule-Cluster. The two chains are logical and textual representations of the same restriction and are not counted as two independent eligibility rules.","chain_bindings":[{"chain_id":"v141-c-R012","ownership":"primary","role":"core","rationale":"Express seller-player eligibility using the existing admission relations and logical constraints."},{"chain_id":"v141-c-R013","ownership":"primary","role":"alternative","rationale":"Retain the single-node textual representation of the same eligibility restriction as an alternative expression rather than a new rule."}],"connections":[{"connection_id":"v142-d-CL005-L001","from_chain_id":"v141-c-R012","to_chain_id":"v141-c-R013","kind":"alternative_representation","from_refs":["v141-c-R012::phi::v141-c-R012-C001"],"to_refs":["v141-c-R013::phi::v141-c-R013-C001"],"evidence_ids":["v141-b-g03-E12"],"rationale":"The same sentence in the source text that states the seller-player restriction is represented respectively as an admission constraint and as a participation fact; the scope and object are consistent; it is not counted repeatedly as an independent rule."}],"object_mappings":[{"mapping_id":"v142-d-CL005-M001","kind":"same_node","member_refs":["v141-c-R012::V::participation.prosumer","v141-c-R013::V::participation.prosumer"],"canonical_ref":"v141-c-R012::V::participation.prosumer","display_policy":"single_representative","evidence_ids":["v141-b-g03-E12"],"rationale":"Both places are the player-participation function of the M03 seller-role prosumer; display normalization does not merge participants across mechanisms."},{"mapping_id":"v142-d-CL005-M002","kind":"alternative_representation","member_refs":["v141-c-R012::phi::v141-c-R012-C001","v141-c-R013::phi::v141-c-R013-C001"],"canonical_ref":null,"display_policy":"linked_distinct","evidence_ids":["v141-b-g03-E12"],"rationale":"Both the logical and procedural textual representations of the same eligibility restriction are retained; their types and bindings differ, and neither original constraint is deleted."}],"gaps":[{"gap_id":"v142-d-CL005-G001","category":"unverified_source","description":"The seller-player restriction is based solely on unaudited candidate evidence permitted by the experiment; existing admission node names do not provide an additional basis for geographical or technical admission.","chain_ids":["v141-c-R012","v141-c-R013"],"object_refs":["v141-c-R012::phi::v141-c-R012-C001","v141-c-R013::phi::v141-c-R013-C001"],"evidence_ids":["v141-b-g03-E12"],"proposal_ids":[],"required_work":"Manually check the scope of players and seller roles referred to in the original text, and confirm the interpretation of the two representations; do not treat assembled as source-verified."}]},"rule_refs":["14-stackelberg_pv_sharing::v141-c-R012","14-stackelberg_pv_sharing::v141-c-R013"],"unresolved_rule_refs":[],"node_ids":["COMP-34f4647dbfb7e00c","COMP-52f5faebc827833c"]});
